def wr(s): return ORSet.from_snapshot(json.loads(json.dumps(s)))
def canon(s): return (json.dumps(s["adds"],sort_keys=True),
                      json.dumps(s["removes"],sort_keys=True),
                      json.dumps(s.get("compacted",{}),sort_keys=True))

random.seed(1234)
# Reference: plain ORSet union of operations; nodes compact randomly.
ELEMS=["e1","e2","e3"]
for trial in range(400):
    ids=["r0","r1","r2","r3"]
    nodes={i:ORSet(ids[i]) for i in range(4)}
    ref=ORSet("ref")
    # maintain an independent plain (never compacted) shadow per node
    shadow={i:ORSet(ids[i]) for i in range(4)}
    for _ in range(random.randint(1,25)):
        op=random.random()
        i=random.randrange(4)
        if op<0.45:
            e=random.choice(ELEMS); nodes[i].add(e); shadow[i].add(e)
        elif op<0.7:
            e=random.choice(ELEMS); nodes[i].remove(e); shadow[i].remove(e)
